<script setup lang="ts">
import { api, friendlyError } from '@lostsky/api/client'
import { useMutation, useQuery, useQueryClient } from '@tanstack/vue-query'
import LsButton from '@lostsky/ui/components/LsButton.vue'
import { computed, reactive, watch } from 'vue'
const client=useQueryClient();const settings=reactive<Record<string,string>>({});const query=useQuery({queryKey:['settings','index'],queryFn:()=>api.get<Record<string,unknown>>('/setting',{app:'index'})});watch(()=>query.data.value,(data)=>{Object.keys(settings).forEach(key=>delete settings[key]);Object.entries(data??{}).forEach(([key,value])=>settings[key]=String(value??''))},{immediate:true});const mutation=useMutation({mutationFn:()=>api.post('/setting',{app_name:'index',settings:{...settings}}),onSuccess:()=>client.invalidateQueries({queryKey:['settings','index']})});const keys=computed(()=>Object.keys(settings));const isSwitch=(key:string)=>['enable','enabled','open','visible','allow','required'].some(word=>key.toLowerCase().includes(word))&&['0','1'].includes(settings[key]??'');const label=(key:string)=>key.replace(/[._-]+/g,' ').replace(/\b\w/g,letter=>letter.toUpperCase())
</script>
<template><form class="settings" @submit.prevent="mutation.mutate()"><header><div><p>INDEX SETTINGS</p><h2>团队设置</h2></div><LsButton type="submit" :loading="mutation.isPending.value">保存设置</LsButton></header><p v-if="query.isError.value" class="error" role="alert">{{friendlyError(query.error.value)}}</p><div v-else-if="query.isPending.value" class="loading"></div><div v-else-if="!keys.length" class="empty"><h3>当前没有可配置项</h3><p>应用注册设置后会自动显示在这里。</p></div><section v-else><label v-for="key in keys" :key="key" :class="{switch:isSwitch(key)}"><span><strong>{{label(key)}}</strong><small>{{key}}</small></span><input v-if="isSwitch(key)" type="checkbox" :checked="settings[key]==='1'" @change="settings[key]=($event.target as HTMLInputElement).checked?'1':'0'"><input v-else v-model="settings[key]" type="text"></label></section><p v-if="mutation.isError.value" class="error" role="alert">{{friendlyError(mutation.error.value)}}</p><p v-if="mutation.isSuccess.value" class="success" role="status">设置已保存。</p></form></template>
<style scoped>.settings{display:grid;gap:1rem;max-width:42rem}.settings header{display:flex;align-items:end;justify-content:space-between;gap:1rem}.settings header p,.settings header h2{margin:0}.settings header p{color:var(--sky-lost-strong);font-family:'Barlow Condensed';font-size:.75rem;font-weight:700;letter-spacing:.06em}.settings section{background:white;border:1px solid var(--line);border-radius:10px;overflow:hidden}.settings section>label{min-height:78px;display:grid;gap:.65rem;padding:1rem;border-bottom:1px solid var(--line)}.settings section>label:last-child{border-bottom:0}.settings label>span strong,.settings label>span small{display:block}.settings label small{margin-top:.2rem;color:var(--muted-ink);font-size:.75rem}.settings input[type=text]{min-height:44px;padding:.6rem .7rem;border:1px solid var(--line);border-radius:8px}.settings input[type=checkbox]{width:24px;height:24px}.settings label.switch{grid-template-columns:1fr auto;align-items:center}.error,.success,.empty{padding:1rem;background:white;border:1px solid var(--line);border-radius:8px}.error{color:var(--danger)}.success{color:var(--success)}.empty{padding:3rem 1rem;text-align:center}.empty p{color:var(--muted-ink)}.loading{height:260px;background:var(--line);border-radius:10px;opacity:.6}</style>
